content:
{
  "is_open_solicitation": true,
  "buyer": "Massachusetts Government Authority (Administrative Services Organization)",
  "title": "SW-121256 - USA (Massachusetts) - Administrative Services Organization - Deadline December 10,2026",
  "due_date": "2026-12-10",
  "fit_score": 55,
  "why_fit": [
    "Massachusetts-based digital agency with hand-coded web application development experience",
    "Offers managed hosting on own servers with daily backups, SSL, and monitoring",
    "Builds iOS/Android apps from single Flutter codebase plus backend",
    "Experience delivering custom software products (Stone Project, Cabinet Project, Belcome, Groundflag)",
    "Local presence in Massachusetts, eligible for onshore requirement"
  ],
  "gaps": [
    "No demonstrated experience with government administrative services or Family Resource Centers",
    "No explicit capability for comprehensive communication strategy (marketing, outreach, media relations, branding)",
    "May lack specific certifications or bonding required for government contracts",
    "No mention of customizable data collection forms, reporting dashboards, or reminder systems in portfolio",
    "Team size may be insufficient for large-scale government project"
  ],
  "requirements": [
    "Digital proposal submission via email or online portal",
    "Questions due by November 2, 2026",
    "Proposal due by December 10, 2026",
    "Onshore (USA organization only)",
    "Offsite work performance"
  ],
  "evidence": [
    {
      "claim": "Buyer is a Massachusetts government authority seeking vendor for administrative services organization.",
      "quote": "Government Authority located in Massachusetts; USA based organization looking for expert vendor for administrative services organization."
    },
    {
      "claim": "Scope includes configurable web-based system with customizable data collection forms, reporting dashboards, and reminders.",
      "quote": "This web-based system should be configurable and support multiple related data relationships. It should include: customizable data collection forms; reporting and dashboard capabilities for individual clients, groups of clients or services, Family Resource Center (FRC), and across multiple Family Resource Centers; and reminders for follow-up."
    },
    {
      "claim": "Vendor must develop and implement comprehensive communication strategy including marketing, outreach, media relations, messaging, branding.",
      "quote": "Develop and implement a comprehensive communication strategy for the FRCs, which shall include but not be limited to marketing, outreach, media relations, messaging and branding development."
    },
    {
      "claim": "Vendor must develop, host, maintain, and manage content for centralized web application.",
      "quote": "Develop, host, maintain and manage content for a centralized web application, using preliminary materials provided by agency, as described by Section 2.02(a), including ensuring that all content is current"
    },
    {
      "claim": "Eligibility limited to onshore USA organizations.",
      "quote": "Onshore (USA Organization Only)"
    },
    {
      "claim": "Work performed offsite.",
      "quote": "Performance of the work will be offsite."
    },
    {
      "claim": "Proposals submitted digitally via email or online.",
      "quote": "Response can be submitted digitally via Email or Online."
    },
    {
      "claim": "Proposal deadline December 10, 2026.",
      "quote": "Expiry Date : Thursday, 10 December, 2026"
    },
    {
      "claim": "Questions deadline November 2, 2026.",
      "quote": "Question Answer Deadline : Monday, 2 November, 2026"
    }
  ]
}
